# board/display/input are separate collaborators
class TicTacToe:
    def __init__(self, board, display, input_handler):
        self.board, self.display, self.input = board, display, input_handler
    def play(self):
        while not self.board.has_winner():
            self.display.render(self.board)      # UI concern
            move = self.input.get_next_move()     # input concern
            self.board.make_move(move)             # rule concern

